const byMethod = (method) => deviceGuides.filter((g) => g.method === method).map((g) => g.name);
const native = byMethod('native');
const bridge = byMethod('third-party');
const partial = byMethod('partial');

export const hubTitle = 'Sync Any Fitness Tracker with Apple Health — P.R.O.';
export const hubDescription = 'Step-by-step guides to sync Garmin, WHOOP, Oura, Polar, COROS, Suunto and more with Apple Health: what each device writes and how to avoid double counting.';

const plural = (names, one, many) => (names.length > 1 ? many : one);
const methodClauses = [
  native.length && `${listOf(native)} ${plural(native, 'writes to it natively through its own app', 'write to it natively through their own apps')}`,
  partial.length && `${listOf(partial)} ${plural(partial, 'writes', 'write')} some data types`,
  bridge.length && `${listOf(bridge)} ${plural(bridge, 'needs', 'need')} a third-party bridge app`,
].filter(Boolean);

